\copy (WITH lr AS (SELECT order_id, review_score FROM (SELECT order_id, review_score, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY review_answer_timestamp DESC) AS rn FROM order_reviews) r WHERE rn = 1) SELECT oe.order_id, oe.is_late, oe.delivery_days, oe.approval_to_carrier_days, oe.carrier_to_customer_days, lr.review_score FROM orders_enriched oe LEFT JOIN lr ON lr.order_id = oe.order_id WHERE oe.in_delivery_population AND oe.purchase_month BETWEEN DATE '2017-01-01' AND DATE '2018-08-01') TO 'data/exports/orders_reviews.csv' WITH (FORMAT csv, HEADER true)

\copy (WITH ss AS (SELECT order_id, MIN(seller_id) AS seller_id FROM order_items GROUP BY order_id HAVING COUNT(DISTINCT seller_id) = 1) SELECT ss.seller_id, s.seller_state, oe.order_id, oe.purchase_month, oe.is_late FROM orders_enriched oe JOIN ss ON ss.order_id = oe.order_id JOIN sellers s ON s.seller_id = ss.seller_id WHERE oe.in_delivery_population AND oe.purchase_month BETWEEN DATE '2017-01-01' AND DATE '2018-08-01') TO 'data/exports/seller_orders.csv' WITH (FORMAT csv, HEADER true)

\copy (WITH items_pop AS (SELECT oi.order_id, oi.price, oi.freight_value, p.product_category_name FROM order_items oi JOIN orders_enriched oe ON oe.order_id = oi.order_id JOIN products p ON p.product_id = oi.product_id WHERE oe.in_delivery_population AND oe.purchase_month BETWEEN DATE '2017-01-01' AND DATE '2018-08-01'), named AS (SELECT ip.*, CASE WHEN ip.product_category_name IS NULL THEN 'unknown' WHEN ip.product_category_name = 'pc_gamer' THEN 'pc_gamer' WHEN ip.product_category_name = 'portateis_cozinha_e_preparadores_de_alimentos' THEN 'portable_kitchen_food_preparers' ELSE COALESCE(ct.product_category_name_english, 'unknown') END AS category_english FROM items_pop ip LEFT JOIN category_translation ct ON ct.product_category_name = ip.product_category_name) SELECT category_english, COUNT(*) AS items, ROUND(SUM(price),2) AS revenue, ROUND(SUM(freight_value),2) AS freight FROM named GROUP BY category_english ORDER BY revenue DESC) TO 'data/exports/category_summary.csv' WITH (FORMAT csv, HEADER true)